rows=[]
def add(domain,parameter,unit,evidence,estimate,source=None,applicability='',transformation='',validation='',uncertainty='',limitation=''):
    bib,url=A[source] if source else ("Uncalibrated synthetic modelling assumption; no observational source.", None)
    rows.append(dict(domain=domain,parameter=parameter,unit=unit,evidence_category=evidence,estimate=estimate,
                     uncertainty=uncertainty,bibliographic_source=bib,url=url,applicability=applicability,
                     transformation=transformation,validation=validation,limitation=limitation))
